import { ClientFinanceData } from "@/lib/types";

// Connect Ecommerce: cliente de serviço (honorário de gestão de contas de marketplace pra
// lojistas), sem CMV. DRE construído inteiro a partir do Contas a Receber (honorários lançados
// no dia 01 de cada competência, um por cliente atendido) e do Contas a Pagar (imposto e
// despesas, calculados como % — ver linhasDestaqueDre abaixo — e também lançados no dia 01).
//
// Fonte: planilha "DRE CONNECT ECOMMERCE 2026" enviada pelo Ewerton, abas "Detalhamento
// {Mês}2026" (um lançamento de honorário por cliente atendido, linhas em vermelho = cliente
// inadimplente naquele mês) — dados reais de Jan a Ago/2026.
//
// Regras aplicadas (a pedido do Ewerton):
// - Receita = soma de TODOS os honorários lançados no Contas a Receber no mês, recebidos ou não.
// - Antes de julho/2026: todo cliente é dado como recebido, mesmo os que apareciam em vermelho
//   na planilha (a inadimplência só passou a ser controlada a partir de julho).
// - A partir de julho/2026: cliente em vermelho fica "pendente" em Contas a Receber (sem
//   recebimento) — é isso que vira a linha "Inadimplência" do DRE.
// - Imposto = sempre 6% da receita do mês.
// - Valor a Gastar = Receita − Imposto − Inadimplência − Investimentos (sem CMV).
// - Comissão Vitor e André = 25% do Valor a Gastar; Comissão Sócios Connect = 25% do Valor a
//   Gastar; Prestação de Serviços CONNECT (despesa administrativa) = 40% do Valor a Gastar.
//
// Observação: a soma dos honorários por cliente (linha a linha) ficou um pouco abaixo do total
// que já estava calculado na aba "Ano 2026" da planilha original pra Jun/Jul/Ago (R$ 842,50 em
// junho, R$ 1.491,00 em julho e agosto — Jan a Mai batem exatos). A pedido do Ewerton, a receita
// desses 3 meses foi ajustada pro valor oficial da planilha: cada mês ganhou um lançamento extra
// em Contas a Receber, cliente "A identificar", descrição "Valor faltante" (ids r290-r292), pra
// fechar a conta enquanto ele apura a origem da diferença — provavelmente um total que não foi
// recalculado na planilha depois de alguma mudança no cadastro de clientes daqueles meses.
// Imposto/Valor a Gastar/Comissões/Despesa Administrativa desses 3 meses já foram recalculados
// com a receita corrigida.
